window.docContents[95].resolve({"/Slang/#Type-Systems--Slang___-Arithmetic-and-Boolean-Expressions--Arithmetic-and-Boolean-Expressions--Syntax":{"contents":"namespace Slang\n\n\n\n\nAbstract syntax trees for arithmetic and boolean expressions:\n\ninductive Aexp where\n  | num (n : Nat)\n  | plus (a₁ a₂ : Aexp)\n  | minus (a₁ a₂ : Aexp)\n  | mult (a₁ a₂ : Aexp)\n\ninductive Bexp where\n  | bool (b : Bool)\n  | eq (a₁ a₂ : Aexp)\n  | neq (a₁ a₂ : Aexp)\n  | le (a₁ a₂ : Aexp)\n  | gt (a₁ a₂ : Aexp)\n  | not (b : Bexp)\n  | and (b₁ b₂ : Bexp)\n\n\n\n\n","context":"Type Systems\u0009Slang: Arithmetic and Boolean Expressions\u0009Arithmetic and Boolean Expressions","header":"2.1.1. Syntax","id":"/Slang/#Type-Systems--Slang___-Arithmetic-and-Boolean-Expressions--Arithmetic-and-Boolean-Expressions--Syntax"}});